using System;using System.IO;using System.Linq;using UnityEngine;using Racer;using Object=UnityEngine.Object;
public static class InspectMountainFaces {public static string Main(){var road=Object.FindAnyObjectByType<RaceDirector>().road;var go=new GameObject("Temp rays",typeof(Camera));var c=go.GetComponent<Camera>();c.fieldOfView=70;c.aspect=1100f/720;var p=road.At(885,out var f);c.transform.SetPositionAndRotation(p+Vector3.up*3-f*6,Quaternion.LookRotation(road.At(915,out _)+Vector3.up*1.5f-(p+Vector3.up*3-f*6)));var old=Physics.queriesHitBackfaces;Physics.queriesHitBackfaces=true;var report="";foreach(var xy in new[]{new Vector2(.18f,.5f),new(.25f,.6f),new(.15f,.35f),new(.8f,.4f),new(.8f,.65f),new(.48f,.66f)}){var hits=Physics.RaycastAll(c.ViewportPointToRay(xy),300,1,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance).Take(4);report+=xy+" "+string.Join(";",hits.Select(h=>h.collider.name+" "+h.point.ToString("F1")))+"\n";}Physics.queriesHitBackfaces=old;Object.DestroyImmediate(go);return report;}}
